SELECT documents.id, documents.content_type, documents.title, documents.summary,
    documents.searchable_text, documents.route_path, documents.published_at,
    documents.updated_at, documents.theme_id FROM () documents

WHERE documents.id > #{afterId}
ORDER BY documents.id LIMIT #{limit}

SELECT documents.id, documents.content_type, documents.title, documents.summary,
    documents.searchable_text, documents.route_path, documents.published_at,
    documents.updated_at, documents.theme_id FROM () documents WHERE documents.id = #{id}
